(function () {
    function init() {
        const container =
            document.getElementById('scroll-gallery') ||
            document.getElementById('infinite-scroll-gallery');

        if (!container || Util.isMobile()) {
            console.warn('justified-gallery: #scroll-gallery or #infinite-scroll-gallery not found.');
            return;
        }

        const config = {
            targetRowHeight: parseInt(getComputedStyle(document.documentElement).getPropertyValue('--jg-target-row-height')) || 225,
            gap: parseInt(getComputedStyle(document.documentElement).getPropertyValue('--jg-gap')) || 4,
            justifyLastRow: false,
            resizeDebounce: 120,
            mutationDebounce: 120,
            // safety caps (you can adjust)
            maxRowHeightMultiplier: 1.4,
            minContainerWidthForFallback: 120
        };

        // simple debounce
        function debounce(fn, wait) {
            let t;
            return function (...args) {
                clearTimeout(t);
                t = setTimeout(() => fn.apply(this, args), wait);
            };
        }

        function itemAspectRatio(itemEl) {
            const img = itemEl.querySelector('img');
            if (!img) return 1;
            if (img.dataset && img.dataset.aspect) return Number(img.dataset.aspect) || 1;
            if (img.hasAttribute('width') && img.hasAttribute('height')) {
                const w = Number(img.getAttribute('width'));
                const h = Number(img.getAttribute('height'));
                if (w > 0 && h > 0) return w / h;
            }
            if (img.naturalWidth && img.naturalHeight) return img.naturalWidth / img.naturalHeight;
            return 1;
        }

        // prefer bounding width but fallback to closest .dateSection width when shrink-wrapped
        function availableContentWidth(el) {
            const rect = el.getBoundingClientRect();
            let w = Math.max(1, Math.floor(rect.width));
            if (w < config.minContainerWidthForFallback) {
                const section = el.closest('.dateSection');
                if (section) {
                    const sRect = section.getBoundingClientRect();
                    const computed = getComputedStyle(section);
                    const padLeft = parseFloat(computed.paddingLeft) || 0;
                    const padRight = parseFloat(computed.paddingRight) || 0;
                    const fallback = Math.max(1, Math.floor(sRect.width - padLeft - padRight));
                    if (fallback > w + 8) w = fallback;
                }
            }
            // clamp to viewport width to avoid transient huge measurements
            const viewportMax = Math.max(1, Math.floor(window.innerWidth - 32));
            if (w > viewportMax) w = viewportMax;
            return w;
        }

        async function waitForSectionImages(sectionEl) {
            const imgs = Array.from(sectionEl.querySelectorAll('img'));
            const galleryImgs = imgs.filter(img => img.id && img.id.startsWith('image'));
            if (!galleryImgs.length) return;
            await Promise.all(galleryImgs.map(img => {
                if (img.decode) return img.decode().catch(() => Promise.resolve());
                if (img.complete && img.naturalWidth) return Promise.resolve();
                return new Promise(res => { img.onload = img.onerror = res; });
            }));
        }

        // compute a compact key for a row to detect meaningful changes
        function computeRowKey(dateBodyEl, items, containerWidth) {
            const aspects = items.map(it => Math.round(it.aspect * 1000)).join(',');
            return `${items.length}|${Math.round(containerWidth)}|${aspects}`;
        }

        // the actual layout function (idempotent and sets settled flag)
        async function layoutDateBody(dateBodyEl) {
            if (!dateBodyEl) return;

            // If row is already settled, check if it's still valid: if key matches skip
            const itemEls = Array.from(dateBodyEl.querySelectorAll('.photo-thumbnail-container'));
            if (itemEls.length === 0) return;

            // ensure images are ready to get accurate aspect ratios
            try { await waitForSectionImages(dateBodyEl); } catch (e) {}

            // compute data
            const containerWidth = availableContentWidth(dateBodyEl);
            const items = itemEls.map(el => ({ el, aspect: itemAspectRatio(el) || 1 }));
            const currentKey = computeRowKey(dateBodyEl, items, containerWidth);
            const prevKey = dateBodyEl.dataset.jgKey || null;
            if (prevKey === currentKey && dateBodyEl.dataset.jgSettled === 'true') {
                // nothing meaningful changed; don't touch DOM
                return;
            }

            // clear inline sizing only if different to avoid writing unnecessarily
            itemEls.forEach(el => {
                if (el.style.width || el.style.height || el.style.marginRight || el.style.marginBottom) {
                    el.style.width = '';
                    el.style.height = '';
                    el.style.marginRight = '';
                    el.style.marginBottom = '';
                }
            });

            // collapse inline whitespace for measurement/display
            dateBodyEl.style.fontSize = '0';
            dateBodyEl.style.lineHeight = '0';

            // build rows by grouping until width at target height would overflow
            const gap = config.gap;
            const targetH = config.targetRowHeight;
            const rows = [];
            let row = [];
            let rowAspectSum = 0;

            items.forEach((it, idx) => {
                row.push(it);
                rowAspectSum += it.aspect;
                const rowWAtTarget = rowAspectSum * targetH + (row.length - 1) * gap;
                if (rowWAtTarget >= containerWidth || idx === items.length - 1) {
                    rows.push({ items: row.slice(), aspectSum: rowAspectSum, isLast: idx === items.length - 1 });
                    row = [];
                    rowAspectSum = 0;
                }
            });

            // prepare sizes (pure calculation)
            const plans = rows.map(r => {
                const rItems = r.items;
                const totalGap = (rItems.length - 1) * gap;

                if (r.isLast && !config.justifyLastRow) {
                    // prefer target height, shrink to fit if required; don't force-fill
                    const widthsAtTarget = rItems.map(it => it.aspect * targetH);
                    const totalWidthAtTarget = widthsAtTarget.reduce((s, w) => s + w, 0) + totalGap;
                    let height = targetH;
                    if (totalWidthAtTarget > containerWidth) {
                        height = (containerWidth - totalGap) / r.aspectSum;
                        if (height < 1) height = 1;
                    }
                    // safety cap
                    const maxAllowed = Math.max(1, Math.round(targetH * config.maxRowHeightMultiplier));
                    if (height > maxAllowed) height = maxAllowed;

                    const widths = rItems.map(it => it.aspect * height);
                    // rounding & scale down if rounding causes overflow
                    let used = widths.map(w => Math.round(w)).reduce((s, v) => s + v, 0);
                    if (used + totalGap > containerWidth && used > 0) {
                        const scale = (containerWidth - totalGap) / used;
                        for (let i = 0; i < widths.length; i++) widths[i] = widths[i] * scale;
                    }

                    return { rItems, heights: rItems.map(() => height), widths, gap, containerWidth };
                } else {
                    // fully-justified row
                    let height = (containerWidth - totalGap) / r.aspectSum;
                    if (height < 1) height = 1;
                    // safety cap to avoid spikes
                    const maxAllowed = Math.max(1, Math.round(targetH * config.maxRowHeightMultiplier));
                    if (height > maxAllowed) height = maxAllowed;

                    let rawWidths = rItems.map(it => it.aspect * height);
                    let roundedWidths = rawWidths.map(w => Math.round(w));
                    let used = roundedWidths.reduce((s, v) => s + v, 0);
                    let discrepancy = containerWidth - totalGap - used;

                    if (discrepancy !== 0 && rItems.length > 0) {
                        // distribute 1px increments across items
                        let remaining = Math.abs(discrepancy);
                        const sign = discrepancy > 0 ? 1 : -1;
                        let i = 0;
                        while (remaining > 0) {
                            roundedWidths[i % rItems.length] += sign;
                            remaining--;
                            i++;
                        }
                    }

                    used = roundedWidths.reduce((s, v) => s + v, 0);
                    if (used + totalGap > containerWidth && used > 0) {
                        const scale = (containerWidth - totalGap) / used;
                        for (let j = 0; j < roundedWidths.length; j++) {
                            roundedWidths[j] = Math.max(1, Math.floor(roundedWidths[j] * scale));
                        }
                    }

                    return { rItems, heights: rItems.map(() => height), widths: roundedWidths, gap, containerWidth };
                }
            });

            // apply in one rAF while disconnecting observer to avoid feedback loops
            requestAnimationFrame(() => {
                stopObserving();
                try {
                    plans.forEach(p => {
                        p.rItems.forEach((it, i) => {
                            const w = Math.max(1, Math.round(p.widths[i]));
                            const h = Math.max(1, Math.round(p.heights[i]));
                            it.el.style.width = w + 'px';
                            it.el.style.height = h + 'px';
                            it.el.style.marginRight = (i < p.rItems.length - 1) ? gap + 'px' : '0px';
                            it.el.style.marginBottom = gap + 'px';
                        });
                    });

                    // mark row as settled and remember key so we don't re-layout unnecessarily
                    dateBodyEl.dataset.jgSettled = 'true';
                    dateBodyEl.dataset.jgKey = currentKey;
                } finally {
                    // reconnect briefly after writes so any real external mutations get observed
                    setTimeout(() => startObserving(), 8);
                }
            });
        }

        function layoutAllSections() {
            const dateSections = container.querySelectorAll('.dateSection');
            dateSections.forEach(section => {
                const row = section.querySelector('.row');
                if (row) {
                    // clear settled flag so layout will run (we want full relayout on window resize)
                    row.dataset.jgSettled = 'false';
                    layoutDateBody(row);
                }
            });
        }

        // observers machinery
        let mo = null;
        let observing = false;
        function startObserving() {
            if (!mo) {
                mo = new MutationObserver(onMutations);
            }
            if (!observing) {
                mo.observe(container, { childList: true, subtree: true });
                observing = true;
            }
        }
        function stopObserving() {
            if (mo && observing) {
                try { mo.disconnect(); } catch (e) {}
                observing = false;
            }
        }

        // When mutations happen: schedule layouts for new rows or rows that lost/gained thumbnails.
        const debouncedSchedule = debounce(function (rows) {
            rows.forEach(row => {
                // mark unsettled and run layout
                if (row && row instanceof Element) {
                    row.dataset.jgSettled = 'false';
                    waitForSectionImages(row).then(() => layoutDateBody(row)).catch(() => layoutDateBody(row));
                }
            });
        }, config.mutationDebounce);

        function onMutations(mutations) {
            // If we're currently performing layout via rAF writes, bail — writes will reconnect observer after finishing.
            // But still schedule a follow-up if necessary (debounced).
            const rowsToLayout = new Set();

            for (const m of mutations) {
                if (m.type !== 'childList') continue;

                // newly added whole date sections (common on infinite scroll)
                m.addedNodes.forEach(node => {
                    if (!(node instanceof Element)) return;
                    if (node.classList.contains('dateSection')) {
                        const row = node.querySelector('.row');
                        if (row) rowsToLayout.add(row);
                        return;
                    }
                    if (node.classList && node.classList.contains('row')) {
                        rowsToLayout.add(node);
                        return;
                    }
                    if (node.classList && node.classList.contains('photo-thumbnail-container')) {
                        const row = node.closest('.row');
                        if (row) rowsToLayout.add(row);
                        return;
                    }
                    // fallbacks: find rows inside added node
                    node.querySelectorAll && node.querySelectorAll('.row').forEach(r => rowsToLayout.add(r));
                    node.querySelectorAll && node.querySelectorAll('.photo-thumbnail-container').forEach(th => {
                        const r = th.closest('.row');
                        if (r) rowsToLayout.add(r);
                    });
                });

                // removed nodes: re-layout parents (they changed)
                m.removedNodes && m.removedNodes.forEach(node => {
                    if (!(node instanceof Element)) return;
                    if (node.classList && node.classList.contains('photo-thumbnail-container')) {
                        const r = node.closest('.row');
                        if (r) rowsToLayout.add(r);
                    }
                });
            }

            if (rowsToLayout.size > 0) {
                debouncedSchedule(Array.from(rowsToLayout));
            }
        }

        const debouncedLayoutAll = debounce(() => {
            // mark all rows unsettled and relayout
            const rows = Array.from(container.querySelectorAll('.dateSection .row'));
            rows.forEach(r => r.dataset.jgSettled = 'false');
            layoutAllSections();
        }, config.resizeDebounce);

        // Public API for manual control
        window.ScrollJustifiedGallery = {
            layoutAll: layoutAllSections,
            layoutDateBody: layoutDateBody,
            waitForSectionImages: waitForSectionImages
        };

        // initial run: layout existing rows, then start observer
        setTimeout(() => {
            const rows = Array.from(container.querySelectorAll('.dateSection .row'));
            Promise.all(rows.map(row => waitForSectionImages(row))).then(() => {
                rows.forEach(row => {
                    row.dataset.jgSettled = 'false';
                    layoutDateBody(row);
                });
                // start observing after initial layout so initial writes don't trigger re-layout loops
                startObserving();
            }).catch(() => {
                rows.forEach(row => {
                    row.dataset.jgSettled = 'false';
                    layoutDateBody(row);
                });
                startObserving();
            });
        }, 20);

        window.addEventListener('resize', debouncedLayoutAll);
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();